mapper.select:
SELECT item_key AS itemKey, COUNT(*) AS totalCount, SUM(CASE WHEN is_correct = 0 THEN 1 ELSE 0 END) AS wrongCount, ROUND(SUM(CASE WHEN is_correct = 0 THEN 1 ELSE 0 END) * 100.0 / COUNT(*), 2 ) AS wrongRate FROM kana_answer_log WHERE is_archived = #{isArchived}
AND answered_at >= #{startDate}
AND answered_at < DATE_ADD(#{endDate}, INTERVAL 1 DAY)
GROUP BY item_key HAVING COUNT(*) >= 3 ORDER BY wrongRate DESC, wrongCount DESC, totalCount DESC LIMIT 10
